SET NAMES utf8mb4; UPDATE rendez_vous SET statut=CONVERT(x'506C616E696669C3A9' USING utf8mb4) WHERE HEX(statut)='506C616E6966693F3F'; ALTER TABLE rendez_vous MODIFY statut VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT CONVERT(x'506C616E696C696669C3A9' USING utf8mb4); SELECT id, statut, HEX(statut) AS hex_statut FROM rendez_vous WHERE statut NOT IN ('Planifié','Réalisé','Annulé','Décalé'); SELECT COLUMN_DEFAULT, HEX(COLUMN_DEFAULT) AS hex_default FROM information_schema.columns WHERE table_schema='contact_filementcrm' AND table_name='rendez_vous' AND column_name='statut';
